-- Recovered from the linked project's Supabase migration history.

-- Real Talk, Every Day human-pilot V3: 280 active first-play cards, 1,520 preserved reserve cards.
-- Generated by scripts/generate-real-talk-v3-content.mjs.

begin;

on conflict(game_id,category_id) do update set label=excluded.label,target_count=excluded.target_count,sort_order=excluded.sort_order,enabled=true,updated_at=now();

create temporary table decked_real_talk_v3_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$
declare matched integer;
begin
  select count(*) into matched from public.content_items item join decked_real_talk_v3_active selected on selected.item_id=item.id where item.game_id='everyday-conversation';
  if matched<>280 then raise exception 'Real Talk V3 inventory mismatch: expected 280 active IDs, found %',matched; end if;
end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='everyday-conversation';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_real_talk_v3_active selected where item.id=selected.item_id and item.game_id='everyday-conversation';

update public.content_item_categories set enabled=false where game_id='everyday-conversation';

select item_id,'everyday-conversation',category_id,sort_order,true from decked_real_talk_v3_active
on conflict(item_id,game_id,category_id) do update set sort_order=excluded.sort_order,enabled=true;

create temporary table decked_real_talk_v3_revisions on commit drop as
select selected.*,item.current_version+1 as next_version
from decked_real_talk_v3_active selected join public.content_items item on item.id=selected.item_id
where selected.revised;

update public.content_item_versions version set editorial_status='superseded'
from decked_real_talk_v3_revisions revised
where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);

select item_id,next_version,body,lower(regexp_replace(body,'[^[:alnum:]'']+',' ','g')),metadata,'published','Real Talk human-pilot V3 editorial revision'
from decked_real_talk_v3_revisions
on conflict(item_id,version) do update set body=excluded.body,normalized_body=excluded.normalized_body,metadata=excluded.metadata,editorial_status='published',change_note=excluded.change_note;

update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now()
from decked_real_talk_v3_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata
from decked_real_talk_v3_active selected join public.content_items item on item.id=selected.item_id
where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='everyday-conversation' and status='published';

values('1368b13e-30b5-55da-a4a8-d24bcba51ed5'::uuid,'everyday-conversation','published',280,280,'ec4d3dbe1369c68f9969c5ccc1fe22822fa1b93408dd700f52d1376cdf891ab8','Real Talk human-pilot V3 first-play release; 1,520 reserve identities preserved.',now())
on conflict(id) do update set status='published',item_count=280,membership_count=280,checksum=excluded.checksum,notes=excluded.notes,published_at=now();

delete from public.content_release_items where release_id='1368b13e-30b5-55da-a4a8-d24bcba51ed5'::uuid;

select '1368b13e-30b5-55da-a4a8-d24bcba51ed5'::uuid,item.id,item.published_version,array[selected.category_id]
from decked_real_talk_v3_active selected join public.content_items item on item.id=selected.item_id
where item.game_id='everyday-conversation' and item.published_version is not null;

commit;
